import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>报名表上最常见的三个数字是50KB、100KB和200KB。它们看起来差不多，压出来的照片却完全不一样。</p>\n<p>选错了，要么上传失败，要么白白扔掉画质。选对了，表格一次就能通过。</p>\n<p>这篇对比会讲清楚每个尺寸对照片的影响、各自适合用在哪里，以及怎样在一分钟内做出决定。</p>\n<h2 id=\"the-short-answer\">先说结论</h2>\n<p>用报名网站允许的最大尺寸。200KB的图片几乎总是比100KB的好看，100KB也比50KB的好。</p>\n<p>只有表格明确要求50KB时，才压到50KB。压得比上限更小，没有任何好处。</p>\n<p>把上限当作天花板，而不是目标。你的任务是在不超标的前提下，保留尽可能多的画质。</p>\n<p>如果没有写明上限，200KB是网上照片的合理默认值。清晰度和速度的平衡做得很好。</p>\n<h2 id=\"what-50kb-looks-like\">50KB看起来是什么样？</h2>\n<p>50KB下的人像依然能认出来，也能正常使用。脸部清晰，轮廓干净，图片能完成它的任务。</p>\n<p>凑近了看，妥协就显出来了。头发少了发丝感，衣服少了织纹，平滑的背景还可能出现淡淡的色带。</p>\n<p>文字是弱点。扫描件里的小字可能会虚到让人费眼睛，不过大号文字依然能看清。</p>\n<p>对它本来的用途来说，50KB够用了。护照网站和考试报名表就是按这个标准设计的，审核的人也习惯了。</p>\n<h2 id=\"what-100kb-looks-like\">100KB看起来是什么样？</h2>\n<p>预算翻倍到100KB，改善肉眼可见。边缘更锐利，皮肤更自然，背景也更平滑。</p>\n<p>100KB的证件照在正常观看尺寸下看起来很好。大多数人根本看不出来它被压缩过。</p>\n<p>截图的改善也很明显。界面文字保持清晰，50KB下发虚的小标签又能看清了。</p>\n<p>这就是100KB成为简历和招聘网站“甜点”的原因。它小到任何系统都能接受，又大到看起来很专业。</p>\n<h2 id=\"what-200kb-looks-like\">200KB看起来是什么样？</h2>\n<p>到了200KB，一张普通的网页照片看起来几乎和原图一模一样。只有逐像素对比才能发现压缩的痕迹。</p>\n<p>商品图受益最大。布料纹理、首饰光泽、包装上的小字，都能在这个体积下保留下来。</p>\n<p>信息图和图表也属于这个档位。细线条和小注释需要额外的数据才能保持锐利。</p>\n<p>博客和网店把200KB当作标准，正是这个原因。页面依然很快，图片也依然有说服力。</p>\n<h2 id=\"side-by-side\">同一张照片，三种尺寸并排看</h2>\n<p>想象一张手机拍的人像。200KB下，头发能看到一根根发丝，衬衫能看到织纹。</p>\n<p>100KB下，发丝会稍微粘连，织纹会变柔和。不过脸部看起来是一样的，而脸部才是最重要的。</p>\n<p>50KB下，头发变成一团平滑的色块，背景还可能出现色带。脸依然清晰，但照片整体感觉更平。</p>\n<p>换成截图，差距会拉得更大。200KB下清晰的文字，100KB下只是能读，50KB下可能就模糊了。</p>\n<h2 id=\"file-size-and-dimensions\">文件大小不是全部</h2>\n<p>尺寸和文件大小一样重要。一张600×600像素的50KB图片，看起来远比一张2000×2000像素的50KB图片好。</p>\n<p>原因是密度。同样的50KB分给更少的像素，每个像素分到的数据就更多，细节保留得更好。</p>\n<p>这就是压缩器在只调画质压不到目标时，会缩小尺寸的原因。一张更小、更清晰的图片，胜过一张更大、更糊的图片。</p>\n<p>报名网站固定了尺寸时，这条路就走不通了。这时格式选择就成了主要的杠杆，WebP常常能帮上忙。</p>\n<h2 id=\"which-size-for-which-job\">什么工作用什么尺寸？</h2>\n<p>护照、签证和考试报名：50KB，因为网站就是这么要求的。用<a href=\"/zh/tupian-yasuo-dao-50kb/\">50KB压缩工具</a>，并对上要求的尺寸。</p>\n<p>简历、招聘网站和头像照片：100KB。用<a href=\"/zh/tupian-yasuo-dao-100kb/\">100KB压缩工具</a>，画质和兼容性的平衡最好。</p>\n<p>博客图片、商品图和作品集照片：200KB。用<a href=\"/zh/tupian-yasuo-dao-200kb/\">200KB压缩工具</a>，保留能帮你卖出东西的细节。</p>\n<p>有自定义上限的表格：用<a href=\"/zh/mubiao-wenjian-daxiao-yasuo/\">目标文件大小压缩工具</a>，直接输入表格要求的数字。</p>\n<h2 id=\"format-effects\">格式如何改变对比结果</h2>\n<p>JPG在三个尺寸下都是最稳妥的格式。每个报名网站都接受它，从50KB到200KB处理照片都很出色。</p>\n<p>WebP通常在每KB的画质上胜出。50KB下它看起来会比JPG明显干净一点，但有些老网站不接受它。</p>\n<p>PNG只适合颜色扁平、边缘锐利的图形。拍照片时它在每个尺寸下都输，因为它减不掉足够的体积。</p>\n<p>实用的规则很简单：用JPG，除非网站接受WebP、而你又需要在50KB下多抠一点画质。</p>\n<h2 id=\"loading-speed\">页面加载速度呢？</h2>\n<p>在网页上，50KB和200KB的差别真实存在，但并不大。一张200KB的首图在正常的网络下加载依然很快。</p>\n<p>真正的风险是累积。十张200KB的图片加起来是2MB，十张50KB的只有500KB。</p>\n<p>一个页面有很多图片时，100KB常常是合适的中间值。它让总重量保持合理，又不会明显伤害任何一张照片。</p>\n<p>只有一张首图时，就用200KB。一张大文件拖不慢页面，画质差别却看得见。</p>\n<h2 id=\"decision-framework\">一分钟决策法</h2>\n<p>第一步，看上限。如果表格写明了数字，这个数字就是决定，讨论到此结束。</p>\n<p>第二步，看格式规则。如果网站不接受WebP，就用JPG，哪怕WebP看起来会好一点点。</p>\n<p>第三步，看内容。文字多的图片比人像需要更多预算，文字重要时就往上选一个档位。</p>\n<p>第四步，测试结果。压到你选定的尺寸，用全尺寸预览一遍，确认没问题再提交。</p>\n<ul>\n<li>网站要求50KB：用50KB工具，JPG或WebP。</li>\n<li>简历或头像照片：100KB，JPG。</li>\n<li>博客或商品照片：200KB，JPG或WebP。</li>\n<li>自定义上限：把精确数字输进目标大小工具。</li>\n<li>文字多的图片：比原计划往上选一个档位。</li>\n</ul>\n<h2 id=\"when-to-use-100kb-instead\">什么时候该从50KB升到100KB？</h2>\n<p>很多人默认选50KB，因为它感觉最保险。但如果表格允许100KB，用50KB只会白白扔掉画质。</p>\n<p>100KB的人像能保留50KB丢掉的头发纹理和衣服细节。对职业形象照来说，这个差别看得见。</p>\n<p>截图受益更大。50KB下发虚的小字，100KB下依然能读，这对证书和表格很重要。</p>\n<p>规则很简单：永远用表格允许的最大尺寸。更小不等于更好，除非表格就是这么要求的。</p>\n<p>如果表格把上限写为100KB，就用<a href=\"/zh/tupian-yasuo-dao-100kb/\">100KB压缩工具</a>，让它在这个预算内把画质拉到最高。</p>\n<h2 id=\"quality-vs-dimensions\">画质与尺寸：真正的取舍</h2>\n<p>压缩有两个杠杆：画质和尺寸。画质决定每个像素扔掉多少细节，尺寸决定一共有多少像素。</p>\n<p>降低画质，图片保持大尺寸但变柔和。缩小尺寸，图片保持锐利但变小。最好的结果是两者平衡。</p>\n<p>工具会先尝试调画质，因为大多数人想保住尺寸。只有画质不够时，它才会逐步缩小尺寸。</p>\n<p>对人像来说，尺寸上小小的一刀常常看不出来。显示尺寸很小时，500像素宽的脸和600像素宽的脸看起来一样。</p>\n<p>对文字来说，尺寸更重要。缩小证件会让字变小，所以文字必须可读时，优先降画质而不是降尺寸。</p>\n<h2 id=\"colour-banding\">色带问题及避免方法</h2>\n<p>色带是指平滑区域出现看得见的条纹，比如天空或干净的墙面。这是小体积下最常见的视觉缺陷。</p>\n<p>色带出现，是因为压缩简化了渐变。只有50KB可用时，一片平滑的天空可能只被存成几条扁平的色带。</p>\n<p>纯色背景的人像最容易中招。本该是一种平滑颜色的影棚背景，可能会出现一圈圈的环。</p>\n<p>同样大小下，WebP处理渐变比JPG稍好一点。如果色带让你在意，先试试WebP输出。</p>\n<p>给背景加一点细微的纹理也有帮助。带一点噪点的背景，能给压缩器一些可以发挥的东西。</p>\n<h2 id=\"choosing-between-the-three\">在三个尺寸之间做选择的实用方法</h2>\n<p>先读表格。如果它写明了尺寸，选择就已经做好了，停下来，直接开始压缩。</p>\n<p>如果表格给的是一个范围，就选范围的顶端。上限200KB就意味着你可以用200KB，你的图片会感谢你。</p>\n<p>接下来看内容。人像在50KB下表现不错，而截图或信息图需要100KB或200KB。</p>\n<p>再想想受众。给政府审核员的照片要清晰，不用漂亮，50KB就够了。作品集照片要让人眼前一亮，就用200KB。</p>\n<p>两个尺寸都行时，两个都预览一下。同一张图片分别压到50KB和100KB，并排看一看，让眼睛来决定。</p>\n<h2 id=\"future-proofing\">让压缩后的图片经得起时间考验</h2>\n<p>原图永远留着。压缩过的图片再也恢复不到完整画质，用什么工具都不行。</p>\n<p>压缩副本用描述性的名字保存。名字里带上尺寸和用途，以后就不用重新压缩。</p>\n<p>不要压缩已经压缩过的文件。每一轮都会叠加损伤，两轮50KB比一轮50KB难看得多。</p>\n<p>报名网站更新规则时，从原图重新压缩。去年为50KB上限做的文件，不一定适合今年的100KB上限。</p>\n<p>把原图当作母版，把每个压缩副本当作一次性的消耗品。这个习惯能保护你的照片很多年。</p>\n<h2 id=\"upload-speeds\">上传速度与慢速网络</h2>\n<p>50KB的文件即使在很弱的网络下也能瞬间上传，而5MB的原图可能直接超时。这份可靠性，也是报名网站要求小文件的原因之一。</p>\n<p>网速慢时，先压缩再打开表格。把一张5MB的照片上传给压缩器，等于浪费了你本来想省下的流量。</p>\n<p>记住，工具是在本地处理文件的。页面加载完成之后，压缩本身完全不需要联网。</p>\n<p>在共享网络或公共网络上，小文件也意味着更少的暴露时间。50KB的上传一眨眼就完成了。</p>\n<p>对网速慢地区的申请人来说，50KB的上限是真心有帮助的。它让流程对所有人都快，而不只是对光纤用户快。</p>\n<h2 id=\"printing-50kb\">50KB的图片能打印吗？</h2>\n<p>能打印，但只能印得很小。护照尺寸的打印没问题，印到A4就会发虚、出现锯齿。</p>\n<p>打印大约需要每英寸300像素。一张600像素宽的图片，印两英寸宽是干净的，正好适合证件照和小幅打印。</p>\n<p>千万别拿50KB的文件去印更大的尺寸。缺失的细节会在图片放大的一瞬间暴露无遗。</p>\n<p>打印用的文件留着原图。50KB的副本是为上传准备的，原图是为其他一切准备的。</p>\n<p>如果报名网站要求你把带照片的表格打印出来，先看打印预览。屏幕上看着不错的照片，印到纸上可能会很粗糙。</p>\n<h2 id=\"accessibility\">无障碍：让压缩图片对每个人都好用</h2>\n<p>压缩后的图片依然要让人看得懂。护照照片必须清晰到让任何审核员都能认出本人。</p>\n<p>高对比度有帮助。脸部和背景反差明显的照片，对所有人来说都更容易看，包括视力不好的审核员。</p>\n<p>不要只靠颜色来区分信息。压缩会让颜色变暗淡，靠颜色区分区域的表格会变得难懂。</p>\n<p>网页图片一定要加描述性的替代文字。一张100KB、替代文字写得好的图片，比一张完美却没有替代文字的图片服务到更多人。</p>\n<p>压缩和无障碍是一回事。清晰、高对比的原图既压得更好，也让每个观众都更容易读懂。</p>\n<p>如果还是不确定，就从100KB开始。它是最宽容的中间尺寸，预览之后再往上或往下调都不迟。</p>\n<p>想深入了解最小的那个尺寸，可以读<a href=\"/zh/blog/tu-pian-ya-suo-dao-50kb-wan-zheng-zhi-nan/\">图片压缩到50KB：完整指南</a>。想看动手操作的步骤，可以参考<a href=\"/zh/blog/ru-he-ba-tu-pian-ya-suo-dao-50kb/\">如何把图片压缩到50KB</a>。100KB和200KB的指南也用同样的细致程度讲了更大的尺寸。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"100KB是不是比50KB好一倍？","answer":"不是严格意义上的一倍，但改善很容易看出来。100KB的人像能保留明显更多的头发和衣服细节，文字也更锐利。从100KB到200KB的提升就小一些，因为大多数照片在100KB下已经看起来很干净了。"},{"question":"报名网站能发现我的图片是51KB而不是50KB吗？","answer":"能。报名系统检查的是精确的字节数，所以51KB通不过50KB的上限，哪怕差别微乎其微。压缩工具会故意瞄准上限以下，通常在48KB到49.9KB之间，留出安全余量。"},{"question":"领英头像应该用哪个尺寸？","answer":"领英没有50KB的上限，所以100KB或200KB更好。200KB的头像最锐利，100KB对小小的圆形裁剪来说也完全够用。只有某个具体表格要求时才用50KB。"},{"question":"文件越大，图片就一定越好看吗？","answer":"到某个程度为止。从50KB到200KB，照片的改善肉眼可见，但从200KB到2MB，在正常观看尺寸下几乎没有提升。多出来的数据基本只保留了不放大就看不见的细节。"},{"question":"为什么我的截图在50KB下比人像难看得多？","answer":"截图里有锐利的边缘和细小的文字，存储起来很贵。人像有大片平滑区域，压缩起来很便宜。文字多的图片需要更大的预算，表格允许时就用100KB或200KB。"},{"question":"表格允许200KB，还有理由用50KB吗？","answer":"没有。用比允许值更小的尺寸，只会白白扔掉画质。永远用表格允许的最大尺寸，让压缩器在这个预算内把画质拉到最高。"}];
